public sealed partial class MainForm:Form {
 readonly Settings settings;readonly AudioEngine audio=new();LocalApi? api;LanServer? lan;readonly ComboBox input=new(),output=new(),monitorOutput=new();readonly CheckBox monitorCheck=new(){Text=T("Sounds selbst mithören","Hear sounds yourself"),AutoSize=true,Checked=true};TrackBar? soundVolume;readonly CheckBox mic=new(){Text=T("Mikrofon beimischen","Mix in microphone"),AutoSize=true,Checked=true};readonly Label status=new(){Text=T("Bereit · Audio ist aus","Ready · audio is off"),AutoSize=true,ForeColor=Color.DimGray};readonly Button start=new(){Text=T("Audio starten","Start audio"),AutoSize=true};readonly NotifyIcon tray=new();
