 public MainForm(bool startHidden=false){
 Text="Sardinöööses Soundboard";MinimumSize=new Size(1080,720);ClientSize=new Size(1536,1024);FormBorderStyle=FormBorderStyle.None;AutoScaleMode=AutoScaleMode.None;Font=new Font("Segoe UI",10);BackColor=Color.FromArgb(245,246,248);StartPosition=FormStartPosition.CenterScreen;
 try{settings=Settings.Load();}catch(Exception e){MessageBox.Show("Konfiguration konnte nicht geladen werden / Could not load settings: "+e.Message);throw;}
 Lang.En=settings.Language=="en";
 var devices=AudioEngine.Devices();foreach(var d in devices.Where(x=>x.Direction=="Render"&&AudioEngine.IsVirtualOutput(x.Name)))output.Items.Add(d);foreach(var d in devices.Where(x=>x.Direction=="Capture"&&!AudioEngine.IsVirtualOutput(x.Name)))input.Items.Add(d);
 foreach(var d in devices.Where(x=>x.Direction=="Render"&&!AudioEngine.IsVirtualOutput(x.Name)))monitorOutput.Items.Add(d);monitorOutput.DisplayMember="Name";monitorOutput.SelectedItem=monitorOutput.Items.Cast<AudioDevice>().FirstOrDefault(d=>d.Id==settings.MonitorId)??monitorOutput.Items.Cast<AudioDevice>().FirstOrDefault(d=>d.Id==DefaultSpeaker())??monitorOutput.Items.Cast<AudioDevice>().FirstOrDefault();monitorCheck.Checked=settings.MonitorEnabled;input.DisplayMember=output.DisplayMember="Name";output.SelectedItem=output.Items.Cast<AudioDevice>().FirstOrDefault(d=>d.Id==settings.OutputId)??output.Items.Cast<AudioDevice>().FirstOrDefault();input.SelectedItem=input.Items.Cast<AudioDevice>().FirstOrDefault(d=>d.Id==settings.MicrophoneId)??input.Items.Cast<AudioDevice>().FirstOrDefault(d=>d.Id==DefaultMicrophone())??input.Items.Cast<AudioDevice>().FirstOrDefault();mic.Checked=settings.MixMicrophone;
 BuildReferenceLayout();InitAutomaticUpdates();Program.Status=text=>{if(!IsDisposed)status.Text=text;};
 BuildTrayMenu();tray.Icon=Icon.ExtractAssociatedIcon(Application.ExecutablePath)??SystemIcons.Application;Icon=tray.Icon;tray.Text="Sardinöööses Soundboard";tray.Visible=true;tray.DoubleClick+=(_,_)=>{Show();WindowState=FormWindowState.Normal;Activate();};Resize+=(_,_)=>{if(WindowState==FormWindowState.Minimized)Hide();};
 audio.Failed+=error=>{if(!IsDisposed)BeginInvoke(()=>{audio.Stop();input.Enabled=output.Enabled=mic.Enabled=monitorOutput.Enabled=monitorCheck.Enabled=true;start.Text=T("Audio starten","Start audio");status.Text=error;});};
 Shown+=(_,_)=>Try(()=>{ReadSettings();settings.Save();if(!Program.TestMode){api=new LocalApi(settings.Token,Dispatch);try{lan=new LanServer(settings,Dispatch);}catch(Exception e){lanError=T("Fehler: Handy-Verbindung (LAN) nicht verfügbar – ","Error: phone connection (LAN) not available – ")+e.Message;}}status.Text=lanError??T("Bereit · StreamDock-Schnittstelle aktiv · Audio startet beim Abspielen","Ready · StreamDock interface active · audio starts when you play");if(settings.AudioEnabled)StartAudio();if(startHidden)Hide();StartDiscordCheck();if(AutoTour&&!settings.TourDone&&!startHidden)BeginInvoke(StartTour);});
 FormClosing+=(_,e)=>{if(!exitRequested&&e.CloseReason==CloseReason.UserClosing){e.Cancel=true;Hide();}};
