 }
 static string DefaultSpeaker(){try{using var en=new NAudio.CoreAudioApi.MMDeviceEnumerator();using var d=en.GetDefaultAudioEndpoint(NAudio.CoreAudioApi.DataFlow.Render,NAudio.CoreAudioApi.Role.Multimedia);return d.ID;}catch{return "";}}
 static string DefaultMicrophone(){try{using var en=new NAudio.CoreAudioApi.MMDeviceEnumerator();using var d=en.GetDefaultAudioEndpoint(NAudio.CoreAudioApi.DataFlow.Capture,NAudio.CoreAudioApi.Role.Communications);return d.ID;}catch{return "";}}
 void ReloadDevices(){var selectedIn=(input.SelectedItem as AudioDevice)?.Id;var selectedOut=(output.SelectedItem as AudioDevice)?.Id;var devices=AudioEngine.Devices();input.Items.Clear();output.Items.Clear();foreach(var d in devices.Where(x=>x.Direction=="Render"&&AudioEngine.IsVirtualOutput(x.Name)))output.Items.Add(d);foreach(var d in devices.Where(x=>x.Direction=="Capture"&&!AudioEngine.IsVirtualOutput(x.Name)))input.Items.Add(d);input.SelectedItem=input.Items.Cast<AudioDevice>().FirstOrDefault(d=>d.Id==selectedIn)??input.Items.Cast<AudioDevice>().FirstOrDefault();output.SelectedItem=output.Items.Cast<AudioDevice>().FirstOrDefault(d=>d.Id==selectedOut)??output.Items.Cast<AudioDevice>().FirstOrDefault();}
 Control SlotCard(int index){var slot=settings.Slots[index];var card=new TableLayoutPanel{Dock=DockStyle.Fill,Margin=new Padding(5),Padding=new Padding(10),BackColor=Color.White,ColumnCount=2,RowCount=5};card.RowStyles.Add(new(SizeType.Absolute,25));card.RowStyles.Add(new(SizeType.Absolute,23));card.RowStyles.Add(new(SizeType.Absolute,32));card.RowStyles.Add(new(SizeType.Absolute,32));card.RowStyles.Add(new(SizeType.Absolute,30));card.ColumnStyles.Add(new(SizeType.Percent,50));card.ColumnStyles.Add(new(SizeType.Percent,50));var name=new TextBox{Text=slot.Name,Dock=DockStyle.Fill,BorderStyle=BorderStyle.None,Font=new Font(Font,FontStyle.Bold),AccessibleName=$"Name Sound {index+1}"};name.Leave+=(_,_)=>{slot.Name=name.Text;settings.Save();};card.Controls.Add(name,0,0);card.SetColumnSpan(name,2);var file=new Label{Text=string.IsNullOrEmpty(slot.File)?"Noch keine Datei":Path.GetFileName(slot.File),AutoEllipsis=true,Dock=DockStyle.Fill,ForeColor=Color.DimGray};card.Controls.Add(file,0,1);card.SetColumnSpan(file,2);var play=new Button{Text=$"{index+1}  {slot.Name}",AutoEllipsis=true,Dock=DockStyle.Fill};play.Click+=(_,_)=>Try(()=>Play(index));var assign=new Button{Text="Datei wählen",Dock=DockStyle.Fill};assign.Click+=(_,_)=>Try(()=>{using var picker=new OpenFileDialog{Filter="Audio|*.wav;*.mp3;*.flac;*.aiff;*.wma;*.m4a|Alle Dateien|*.*",Title=$"Sound {index+1} zuweisen"};if(picker.ShowDialog(this)!=DialogResult.OK)return;using var probe=new AudioFileReader(picker.FileName);if(probe.TotalTime.TotalSeconds<=0)throw new InvalidDataException("Audiodatei ist leer.");slot.File=picker.FileName;slot.TrimStart=slot.TrimEnd=0;slot.SourceUrl="";slot.Name=name.Text=Path.GetFileNameWithoutExtension(slot.File);play.Text=$"{index+1}  {slot.Name}";file.Text=Path.GetFileName(slot.File);settings.Save();});card.Controls.Add(play,0,2);card.Controls.Add(assign,1,2);var gain=new NumericUpDown{Minimum=0,Maximum=400,Increment=5,Value=(decimal)Math.Round(Math.Clamp(slot.Volume,0,4)*100),Dock=DockStyle.Fill,AccessibleName=$"Verstärkung Sound {index+1} in Prozent"};slotGains[index]=gain;gain.ValueChanged+=(_,_)=>{slot.Volume=(float)gain.Value/100;audio.SetSlotVolume(slot);settings.Save();};card.Controls.Add(new Label{Text="Pegel %",AutoSize=true,Padding=new Padding(0,5,0,0)},0,3);card.Controls.Add(gain,1,3);var link=new Button{Text="MyInstants-Link",Dock=DockStyle.Fill};link.Click+=async(_,_)=>{using var dialog=new Form{Text="MyInstants verknuepfen",Size=new Size(650,180),StartPosition=FormStartPosition.CenterParent};var url=new TextBox{Dock=DockStyle.Top,Text=slot.SourceUrl,PlaceholderText="https://www.myinstants.com/.../instant/..."};var import=new Button{Text="Verknuepfen",Dock=DockStyle.Bottom,DialogResult=DialogResult.OK};dialog.Controls.Add(url);dialog.Controls.Add(import);dialog.AcceptButton=import;if(dialog.ShowDialog(this)!=DialogResult.OK)return;link.Enabled=false;try{var result=await MyInstants.Import(url.Text.Trim());slot.File=result.File;slot.TrimStart=slot.TrimEnd=0;slot.SourceUrl=result.Source;slot.Name=result.Name;name.Text=slot.Name;play.Text=$"{index+1}  {slot.Name}";file.Text=Path.GetFileName(slot.File);settings.Save();status.Text="MyInstants verknuepft: "+slot.Name;}catch(Exception e){status.Text=e.Message;}finally{link.Enabled=true;}};card.Controls.Add(link,0,4);card.SetColumnSpan(link,2);DeckTheme.Apply(card);return card;}
 void ReadSettings(){settings.OutputId=(output.SelectedItem as AudioDevice)?.Id??"";settings.MicrophoneId=(input.SelectedItem as AudioDevice)?.Id??"";settings.MixMicrophone=mic.Checked;settings.MonitorEnabled=monitorCheck.Checked;settings.MonitorId=(monitorOutput.SelectedItem as AudioDevice)?.Id??"";}
 void StartAudio(){ReadSettings();if(settings.OutputId=="")throw new InvalidOperationException(T("Kein aktives virtuelles CABLE-Gerät gefunden.","No active virtual CABLE device found."));audio.Start(settings);settings.AudioEnabled=true;input.Enabled=output.Enabled=mic.Enabled=monitorOutput.Enabled=monitorCheck.Enabled=false;settings.Save();start.Text=T("Audio beenden","Stop audio");status.Text=T("Audio aktiv · Sounds und Mikrofon am gewählten virtuellen Eingang","Audio on · sounds and microphone go to the selected virtual input");}
 void Play(int index){if(!File.Exists(settings.Slots[index].File))throw new InvalidOperationException(T($"Sound {index+1}: bitte zuerst eine Audiodatei wählen.",$"Sound {index+1}: please choose an audio file first."));if(!audio.Running)StartAudio();audio.Play(settings.Slots[index]);status.Text=T("Spielt: ","Playing: ")+settings.Slots[index].Name;deck.Invalidate();}
 object Dispatch(string command,int slot){if(command=="gain"){int index=slot/401;int percent=slot%401;if(index<0||index>=settings.Slots.Count||percent<0||percent>400)throw new ArgumentException("Ungueltiger Pegel");bool keepDraft=index==selectedSound&&TrimDirty;if(slotGains.TryGetValue(index,out var control)&&!control.IsDisposed)control.Value=percent;else{settings.Slots[index].Volume=percent/100f;audio.SetSlotVolume(settings.Slots[index]);settings.Save();}if(index==selectedSound&&!keepDraft){draftGain=settings.Slots[index].Volume;SyncSelected();}deck.Invalidate();return new{ok=true};}if(command=="volume"){int percent=Math.Clamp((int)Math.Round(settings.MasterVolume*100)+slot*2,0,100);if(soundVolume!=null)soundVolume.Value=percent;else{settings.MasterVolume=percent/100f;audio.SetVolume(settings.MasterVolume,settings.MicrophoneVolume);settings.Save();}return new{ok=true,volumePercent=percent};}if(command=="show"){Show();WindowState=FormWindowState.Normal;Activate();return new{ok=true};}if(command=="status"){var playing=audio.PlayingIds();return new{perSoundStop=true,ok=true,running=audio.Running,volumePercent=(int)Math.Round(settings.MasterVolume*100),monitorEnabled=settings.MonitorEnabled,monitoring=audio.Monitoring,mirroredNonzero=audio.MirroredNonzero,renderedNonzero=audio.RenderedNonzero,slots=settings.Slots.Select((s,i)=>new{id=i+1,soundId=s.Id,playing=playing.Contains(s.Id),name=s.Name,volumePercent=(int)Math.Round(s.Volume*100),assigned=File.Exists(s.File)}).ToArray()};}if(command=="stop-slot"){if(slot<0||slot>=settings.Slots.Count)throw new ArgumentOutOfRangeException(nameof(slot));var target=settings.Slots[slot];audio.StopSlot(target);deck.Invalidate();return new{ok=true,soundId=target.Id,playing=false};}if(command=="stop"){audio.StopSounds();return new{ok=true};}if(command=="play"){Play(slot);return new{ok=true,soundId=settings.Slots[slot].Id,playing=audio.IsPlaying(settings.Slots[slot])};}throw new InvalidOperationException("Unbekannter Befehl");}
 void Try(Action action){try{action();}catch(Exception e){status.Text=e.Message;}}
